import { z } from "zod";

/**
 * Invite token as generated by `regenerate_group_invite`: 24 random bytes in url-safe base64
 * (32 chars, no padding). A value that fails this is treated like an unknown token, never a 400.
 */
export const inviteTokenSchema = z.string().regex(/^[A-Za-z0-9_-]{32}$/);

export const regenerateInviteSchema = z.object({
  group_id: z.uuid(),
});
